     * The single shared log tag every diagnostic line in the app
     * uses. The acceptance test (`grep 'const val TAG'`) asserts
     * there is one and only one definition of `TAG` in
     * `app/src/main/`.
     */
    const val TAG = "ConvoScribe"

    /**
     * Verbose-level message. Sparingly used so a typical recording
     * session does not flood the log.
     */
    fun v(tag: String = TAG, message: String) {
        Log.v(tag, message)
    }

    /** Informational message; the default level for app events. */
    fun i(tag: String = TAG, message: String) {
        Log.i(tag, message)
    }

